const input = $json ?? {};
const deal = input.deal ?? input.transaction ?? input;
const exception = input.exception ?? input.milestone_exception ?? {};
const resolution = input.resolution ?? input.recovery ?? {};
const exceptionStatus = String(exception.status ?? input.status ?? '').toLowerCase();
const resolutionStatus = String(resolution.status ?? '').toLowerCase();
const evidencePresent = Boolean(resolution.evidence ?? resolution.evidence_url ?? resolution.confirmation);
const blockerResolved = Boolean(resolution.blocker_resolved ?? resolution.resolved);
const nextDueDate = resolution.next_due_date ? new Date(resolution.next_due_date) : null;
const nextDueValid = Boolean(nextDueDate && !Number.isNaN(nextDueDate.getTime()));

const identityComplete = Boolean(deal.deal_id ?? deal.transaction_id) &&
  Boolean(deal.property_id) &&
  Boolean(deal.lead_id ?? deal.seller_id);
const executed = String(deal.execution_state ?? deal.agreement?.execution_state ?? '').toLowerCase() === 'executed';
const signedEvidence = Boolean(deal.signed_evidence ?? deal.agreement?.signed_evidence);

let disposition = 'recovery_pending';
let severity = 'high';

if (!identityComplete || !executed || !signedEvidence) {
  disposition = 'human_review';
  severity = 'urgent';
} else if (['resolved','completed','cleared','closed'].includes(resolutionStatus) && (blockerResolved || evidencePresent || nextDueValid)) {
  disposition = 'recovered';
  severity = 'normal';
} else if (['failed','rejected','cancelled','terminated'].includes(resolutionStatus)) {
  disposition = 'escalate';
  severity = 'urgent';
} else if (resolutionStatus === 'in_progress' || resolutionStatus === 'pending') {
  disposition = 'recovery_pending';
  severity = 'high';
} else if (exceptionStatus === 'resolved' && (evidencePresent || blockerResolved)) {
  disposition = 'recovered';
  severity = 'normal';
}

const routing = disposition === 'recovered'
  ? {next_workflow:'WF-136',reason:'Exception resolved; resume critical-date and milestone monitoring.'}
  : disposition === 'recovery_pending'
    ? {next_workflow:'WF-155',reason:'Recovery remains open; continue closing milestone orchestration.'}
    : {next_workflow:'WF-126',reason:'Exception cannot be safely resolved automatically and requires closing coordination/human escalation.'};

return [{
  json:{
    ...input,
    workflow_id:'WF-174',
    workflow_name:'Closing Exception Resolution → Milestone Recovery Controller',
    identity_complete:identityComplete,
    execution_state:deal.execution_state ?? deal.agreement?.execution_state ?? null,
    signed_evidence_present:signedEvidence,
    exception:{
      type:exception.type ?? null,
      status:exceptionStatus,
      milestone_id:exception.milestone_id ?? null,
      blocker:exception.blocker ?? null
    },
    resolution:{
      status:resolutionStatus || null,
      evidence_present:evidencePresent,
      blocker_resolved:blockerResolved,
      next_due_date:resolution.next_due_date ?? null,
      next_due_date_valid:nextDueValid
    },
    decision:{disposition,severity},
    routing
  }
}];

const out = $json ?? {};
return [{
  json:{
    ...out,
    workflow_id:'WF-174',
    result:'closing_exception_recovery_evaluated',
    next_workflow:out.routing?.next_workflow ?? 'WF-126'
  }
}];
